#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    long long maxYSum(std::vector<std::vector<int>>& points) {
        std::unordered_map<int, int> best_y;
        for (const auto& pt : points) {
            int x = pt[0], y = pt[1];
            if (best_y.find(x) == best_y.end() || y > best_y[x]) {
                best_y[x] = y;
            }
        }
        if (best_y.size() < 3) return -1;
        std::vector<int> vals;
        vals.reserve(best_y.size());
        for (auto& pair : best_y) vals.push_back(pair.second);
        std::sort(vals.rbegin(), vals.rend());
        return (long long)vals[0] + vals[1] + vals[2];
    }
};

import java.util.*;

class Solution {
    public long maxYSum(int[][] points) {
        Map<Integer, Integer> bestY = new HashMap<>();
        for (int[] pt : points) {
            int x = pt[0], y = pt[1];
            bestY.put(x, Math.max(bestY.getOrDefault(x, Integer.MIN_VALUE), y));
        }
        if (bestY.size() < 3) return -1;
        List<Integer> vals = new ArrayList<>(bestY.values());
        vals.sort(Collections.reverseOrder());
        return (long) vals.get(0) + vals.get(1) + vals.get(2);
    }
}

