var maxYSum = function(points) {
    const bestY = new Map();
    for (const [x, y] of points) {
        if (!bestY.has(x) || y > bestY.get(x)) {
            bestY.set(x, y);
        }
    }
    if (bestY.size() < 3) return -1;
    const vals = Array.from(bestY.values()).sort((a, b) => b - a);
    return vals[0] + vals[1] + vals[2];
};
